'use strict';
const GC_ARTIFACT_URL='https://www.museum.go.kr/MUSEUM/contents/M0502000000.do?relicId=2040&schM=view&searchId=search';
function dolmenComparison(){return `<section class="source-reading"><h3>실제 유적 사진과 재구성 그림을 비교해요</h3><div class="source-axes"><figure class="source-image"><img src="assets/gochang-dolmen-steve46814.webp" alt="큰 덮개돌과 받침돌이 보이는 고창 죽림리 고인돌 실제 사진"><figcaption>고창 죽림리 고인돌 사진 · Steve46814, 2006<br>CC BY-SA 3.0 · 원본 화면 유지, 무손실 WebP 형식 변환<br><a href="https://commons.wikimedia.org/wiki/File:Korea-Gwangju-Gochang_Dolmens_5303-06.JPG" target="_blank" rel="noopener noreferrer">사진 출처 ↗</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">이용 조건 ↗</a></figcaption></figure><figure class="source-image"><img src="assets/gaecheon-dolmen.webp" alt="반듯한 받침돌과 수평 덮개돌을 상상하여 표현한 고인돌 삽화"><figcaption>앱의 탁자식 고인돌 재구성 그림<br>특정 유적의 사진이나 정확한 복원이 아니에요.</figcaption></figure></div><p>덮개돌과 받침돌에서 같은 점과 다른 점을 찾아요. 이 사진 한 장으로 고조선의 국경이나 정확한 건국 날짜를 알 수는 없어요.</p></section>`}
window.dolmenComparison=dolmenComparison;
function samgukReading(){const r=window.LEARNING_RESOURCES.samguk;return `<section class="source-reading"><h3>${esc(r.title)}</h3>${r.quotes.map(q=>`<b>${esc(q.label)}</b><blockquote lang="zh">${esc(q.original)}</blockquote><p>수업용 풀이 · ${esc(q.paraphrase)}</p>`).join('')}<small>${esc(r.limit)}</small><p><a href="${r.url}" target="_blank" rel="noopener noreferrer">원문·번역 전체 보기 ↗</a></p></section>`}
function artifactObservation(){const r=window.LEARNING_RESOURCES.artifact;return `<section class="artifact-observation" aria-label="동검 자료를 읽는 세 가지 범위">${[['사진에서 볼 수 있는 것',r.photo],['소장품 설명에서 알게 된 것',r.metadata],['이 자료로 확인할 수 없는 것',r.unknown]].map(([title,text])=>`<article><h3>${title}</h3><p>${esc(text)}</p></article>`).join('')}</section>`}
function evidencePair(){return `<div class="source-axes"><article><h3>문헌</h3><p>『삼국유사』에 단군 이야기가 기록되어 전해져요.</p><small>이야기가 기록됐다는 것과 장면이 모두 사실이라는 것은 달라요.</small>${samgukReading()}</article><article><h3>출토 유물</h3><img class="student-artifact" src="assets/bronze-dagger-songgukri.webp" alt="부여 송국리 출토 비파형 동검 실제 소장품 사진"><small>국립중앙박물관 신수3094 · 공공누리 제1유형 출처표시</small>${artifactObservation()}<a href="${GC_ARTIFACT_URL}" target="_blank" rel="noopener noreferrer">소장품 정보 보기 ↗</a></article></div>`}
function draftField(id,label,placeholder=''){return `<label class="reflection" for="gc-${id}">${label}<textarea id="gc-${id}" data-gc-draft="${id}" maxlength="500" placeholder="${placeholder}">${esc(state.activity.drafts?.[id]||'')}</textarea></label>`}
window.gaecheonInquiryBody=function(tab){const grade=state.grade,young=grade==='1-2';if(young)return null;
 if(tab==='story'){
  if(grade==='3-4')return `${tabHeading('이야기와 자료를 나란히 봐요','자료가 보여 주는 것과 아직 확인하지 못한 것을 나누어 생각해요.')} ${evidencePair()}${draftField('compare','두 자료가 알려 주는 점은 어떻게 다른가요?','기록은 …을 전하고, 유물은 …을 보여 줘요.')}${draftField('compareLimit','각 자료로 확인할 수 없는 것은 무엇인가요?','문헌만으로 … / 유물만으로 …')}${draftField('compareRevision','짝의 질문과 그 질문을 듣고 고친 점','질문: … / 고친 설명: …')}<p class="feedback">짝이 “무엇을 보고 그렇게 생각했어?”라고 물으면 자료를 가리켜 설명해요.</p>`;
  const timeline=GAECHEON_DATA.grades[grade].slides.find(s=>s.kind==='timeline');
  const chronology=`<section class="learning-evidence"><h3>기념일의 과정</h3><ul>${timeline.timeline.map(t=>`<li><b>${esc(t.year)}</b> · ${esc(t.text)}</li>`).join('')}</ul><p>위 문헌·사진과 교사 화면의 자료 출처를 함께 확인하세요.</p></section>`;
  return `${tabHeading('나의 주장을 근거로 고쳐요','문헌·유물·연표를 보고, 처음 주장과 고친 주장을 비교해요.')} ${evidencePair()}${chronology}<p class="claim-starter">살펴볼 주장: “단군이 정확히 양력 10월 3일 나라를 세웠다.”</p>${draftField('claim','근거에 맞게 고친 주장','개천절은 …을 기념하는 날이다.')}${draftField('evidence','자료에서 찾은 근거','문헌·유물·연표 중 어떤 자료의 무엇을 보았나요?')}${draftField('limit','이 자료만으로 확인할 수 없는 것','정확한 고대 사건 날짜는 …')}${draftField('revision','짝의 질문을 듣고 더 고친 점','처음에는 …라고 썼지만 …로 고쳤어요.')}<p class="feedback">좋은 설명은 주장·근거·한계를 연결해요. 정답 문장을 그대로 복사할 필요는 없어요.</p>`;
 }
 if(tab==='class'){
  const rows=[{title:'『삼국유사』의 단군 이야기',kind:'문헌',can:'이 이야기가 기록되어 전해진 것',cannot:'곰이 실제로 사람으로 변한 것'},{title:'송국리 출토 비파형 동검 사진과 소장품 정보',kind:'출토 유물',can:'청동을 다루는 기술과 유물의 모양',cannot:'단군의 정확한 건국 날짜'},{title:'앱의 청동기 마을 그림',kind:'현대 재구성',can:'교육용으로 재구성한 생활 모습',cannot:'특정 마을의 모습이 정확히 이랬다는 것'}];
  return `${tabHeading('자료 종류와 확인 범위는 달라요','먼저 자료의 형태를 고르고, 그 자료로 무엇을 말할 수 있는지 살펴봐요.')}${dolmenComparison()}<div class="class-list">${rows.map((r,i)=>`<article class="class-row"><b>${r.title}</b><div>${['문헌','출토 유물','현대 재구성'].map(kind=>`<button data-class="${i}" data-value="${kind}" aria-pressed="${state.activity.classes[i]===kind}">${kind}</button>`).join('')}</div>${state.activity.classes[i]?`<p class="feedback">${state.activity.classes[i]===r.kind?'자료의 형태를 잘 찾았어요.':'자료가 어떻게 만들어졌는지 다시 살펴보세요.'}</p><div class="source-axes"><article><h3>뒷받침하는 것</h3><p>${r.can}</p></article><article><h3>확인하지 못하는 것</h3><p>${r.cannot}</p></article></div>`:''}</article>`).join('')}</div>${grade==='5-6'?draftField('sourceReason','자료 하나를 골라 판단 이유를 적어요','이 자료는 …이므로 …까지 말할 수 있어요.'):'<p>자료가 남아 있다는 사실과 이야기의 모든 장면이 사실이라는 판단은 달라요.</p>'}`;
 }
 if(tab==='act'&&grade==='5-6')return `${tabHeading('좋은 뜻과 상대의 선택을 함께 생각해요','친구가 도움을 원하지 않는데 모둠은 대신 해 주려 해요. 또 한 사람에게 역할이 몰려 있어요.')}<div class="learning-evidence"><h2>무엇을 먼저 물어볼까요?</h2><p>친구의 의사, 각자의 부담, 실행 가능한 방법을 함께 고려해요. 한 가지 정답으로 다른 생각을 지우지 않아요.</p></div>${draftField('consent','상대에게 먼저 물어볼 말','어떤 도움이 필요한지 …')}${draftField('plan','함께 정할 실행 방법과 역할','원하지 않으면 … / 역할은 …')}${draftField('reason','모두에게 이로운 까닭','상대의 선택을 존중하고 …')}${draftField('planRevision','다른 의견을 듣고 고칠 부분','모둠 의견을 듣고 …을 고쳐요.')}<p class="feedback">확인 기준: 상대 의사 존중 · 역할의 구체성 · 실행 가능성 · 근거 있는 까닭</p>`;
 return null;
};
document.addEventListener('input',e=>{if(e.target.dataset.gcDraft){state.activity.drafts||={};state.activity.drafts[e.target.dataset.gcDraft]=e.target.value}});
